[{"order":1,"type":"heading","text":"Angular Component Communication"},{"order":2,"type":"paragraph","text":"Angular applications are built using a component-based architecture. Effective communication between these components is crucial for building dynamic and interactive user interfaces. This tutorial covers three primary communication patterns: Parent to Child, Child to Parent, and Sibling to Sibling."},{"order":3,"type":"subheading","text":"1. Parent to Child Communication"},{"order":4,"type":"paragraph","text":"Parent components can pass data to child components using Input properties. This allows the parent to configure or provide data to the child."},{"order":5,"type":"bullet_point","text":"Use the @Input() decorator in the child component to declare an input property."},{"order":6,"type":"code","text":"// Child Component (child.component.ts)
import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-child',
  templateUrl: './child.component.html',
  styleUrls: ['./child.component.css']
})
export class ChildComponent {
  @Input() message: string = '';
}"},{"order":7,"type":"code","text":"<!-- Child Component Template (child.component.html) -->
<p>Message from Parent: {{ message }}</p>"},{"order":8,"type":"code","text":"// Parent Component (parent.component.ts)
import { Component } from '@angular/core';

@Component({
  selector: 'app-parent',
  templateUrl: './parent.component.html',
  styleUrls: ['./parent.component.css']
})
export class ParentComponent {
  parentMessage = 'Hello from Parent!';
}"},{"order":9,"type":"code","text":"<!-- Parent Component Template (parent.component.html) -->
<app-child [message]="parentMessage"></app-child>"},{"order":10,"type":"paragraph","text":"In this example, the 'parentMessage' property in the parent component is bound to the 'message' input property of the child component using property binding '[message]="parentMessage"'."},{"order":11,"type":"subheading","text":"2. Child to Parent Communication"},{"order":12,"type":"paragraph","text":"Child components can communicate with parent components using Output properties and EventEmitter. This allows the child to notify the parent of events or data changes."},{"order":13,"type":"bullet_point","text":"Use the @Output() decorator and EventEmitter in the child component."},{"order":14,"type":"code","text":"// Child Component (child.component.ts)
import { Component, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-child',
  templateUrl: './child.component.html',
  styleUrls: ['./child.component.css']
})
export class ChildComponent {
  @Output() messageEvent = new EventEmitter<string>();

  sendMessage() {
    this.messageEvent.emit('Message from Child!');
  }
}"},{"order":15,"type":"code","text":"<!-- Child Component Template (child.component.html) -->
<button (click)="sendMessage()">Send Message to Parent</button>"},{"order":16,"type":"code","text":"// Parent Component (parent.component.ts)
import { Component } from '@angular/core';

@Component({
  selector: 'app-parent',
  templateUrl: './parent.component.html',
  styleUrls: ['./parent.component.css']
})
export class ParentComponent {
  message = '';

  receiveMessage($event: string) {
    this.message = $event;
  }
}"},{"order":17,"type":"code","text":"<!-- Parent Component Template (parent.component.html) -->
<app-child (messageEvent)="receiveMessage($event)"></app-child>
<p>Message from Child: {{ message }}</p>"},{"order":18,"type":"paragraph","text":"In this example, the child component emits a 'messageEvent' when the button is clicked. The parent component listens for this event using event binding '(messageEvent)="receiveMessage($event)"' and updates its 'message' property."},{"order":19,"type":"subheading","text":"3. Sibling to Sibling Communication"},{"order":20,"type":"paragraph","text":"Sibling components, which don't have a direct parent-child relationship, can communicate using a shared service. This service acts as a central point for data sharing and event handling."},{"order":21,"type":"bullet_point","text":"Create a shared service using 'ng generate service'."},{"order":22,"type":"code","text":"// Shared Service (data.service.ts)
import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  private messageSource = new Subject<string>();
  message$ = this.messageSource.asObservable();

  sendMessage(message: string) {
    this.messageSource.next(message);
  }
}"},{"order":23,"type":"code","text":"// Component 1 (component1.ts)
import { Component } from '@angular/core';
import { DataService } from './data.service';

@Component({
  selector: 'app-component1',
  templateUrl: './component1.html',
  styleUrls: ['./component1.css']
})
export class Component1 {
  constructor(private dataService: DataService) {}

  sendMessage() {
    this.dataService.sendMessage('Message from Component 1!');
  }
}"},{"order":24,"type":"code","text":"<!-- Component 1 Template (component1.html) -->
<button (click)="sendMessage()">Send Message</button>"},{"order":25,"type":"code","text":"// Component 2 (component2.ts)
import { Component, OnInit } from '@angular/core';
import { DataService } from './data.service';

@Component({
  selector: 'app-component2',
  templateUrl: './component2.html',
  styleUrls: ['./component2.css']
})
export class Component2 implements OnInit {
  message: string = '';

  constructor(private dataService: DataService) {}

  ngOnInit() {
    this.dataService.message$.subscribe(message => {
      this.message = message;
    });
  }
}"},{"order":26,"type":"code","text":"<!-- Component 2 Template (component2.html) -->
<p>Message: {{ message }}</p>"},{"order":27,"type":"paragraph","text":"In this example, 'Component1' sends a message using the 'DataService', and 'Component2' subscribes to the 'message$' observable in the 'DataService' to receive the message. Both components need to be declared in the same module or a shared module."}]
